* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background-color: #f5f5f5;
    padding: 20px;
}

.container {
    max-width: 1600px;
    margin: 0 auto;
    background-color: white;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    padding: 30px;
}

h1 {
    text-align: center;
    color: #333;
    margin-bottom: 30px;
    font-size: 28px;
}

h2 {
    color: #555;
    margin-bottom: 20px;
    font-size: 18px;
    border-bottom: 2px solid #e0e0e0;
    padding-bottom: 10px;
}

.content {
    display: flex;
    gap: 40px;
    min-height: 600px;
}

.chart-section {
    flex: 1;
    display: flex;
    flex-direction: column;
}

.table-section {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

#bubble-chart-container {
    flex: 1;
    position: relative;
    min-height: 500px;
    background-color: #fafafa;
    border-radius: 4px;
    border: 1px solid #e0e0e0;
}

#bubble-chart {
    width: 100%;
    height: 100%;
}

svg circle {
    cursor: pointer;
    transition: opacity 0.2s ease;
}

svg circle:hover {
    opacity: 0.8;
    stroke-width: 2px;
}

#legend {
    margin-top: 20px;
    display: flex;
    flex-wrap: wrap;
    gap: 15px;
}

.legend-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
}

.legend-color {
    width: 16px;
    height: 16px;
    border-radius: 2px;
    border: 1px solid #999;
}

#table-container {
    flex: 1;
    overflow-y: auto;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    background-color: #fafafa;
}

table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

thead {
    position: sticky;
    top: 0;
    background-color: #f0f0f0;
    z-index: 10;
}

th {
    padding: 12px;
    text-align: left;
    font-weight: 600;
    color: #333;
    border-bottom: 2px solid #ddd;
    background-color: #f0f0f0;
}

td {
    padding: 12px;
    border-bottom: 1px solid #e0e0e0;
    color: #555;
}

tbody tr {
    transition: background-color 0.2s ease;
}

tbody tr:hover {
    background-color: #f9f9f9;
}

tbody tr.selected {
    background-color: #e3f2fd;
    font-weight: 600;
}

.tooltip {
    position: fixed;
    background-color: rgba(0, 0, 0, 0.9);
    color: white;
    padding: 10px 15px;
    border-radius: 4px;
    font-size: 12px;
    pointer-events: none;
    z-index: 1000;
    white-space: nowrap;
    max-width: 250px;
    white-space: normal;
}

/* Responsive design */
@media (max-width: 1200px) {
    .content {
        flex-direction: column;
        gap: 30px;
    }

    #bubble-chart-container {
        min-height: 400px;
    }
}

/* Scrollbar styling */
#table-container::-webkit-scrollbar {
    width: 8px;
}

#table-container::-webkit-scrollbar-track {
    background: #f1f1f1;
}

#table-container::-webkit-scrollbar-thumb {
    background: #888;
    border-radius: 4px;
}

#table-container::-webkit-scrollbar-thumb:hover {
    background: #555;
}

