// Parse CSV data
function parseCSV(text) {
    const lines = text.trim().split('\n');
    const headers = lines[0].split(',').map(h => h.trim());
    const data = [];

    for (let i = 1; i < lines.length; i++) {
        const obj = {};
        let currentIndex = 0;
        let currentValue = '';
        let insideQuotes = false;

        for (let j = 0; j < lines[i].length; j++) {
            const char = lines[i][j];

            if (char === '"') {
                insideQuotes = !insideQuotes;
            } else if (char === ',' && !insideQuotes) {
                obj[headers[currentIndex]] = currentValue.trim().replace(/^"|"$/g, '');
                currentValue = '';
                currentIndex++;
            } else {
                currentValue += char;
            }
        }

        if (currentIndex < headers.length) {
            obj[headers[currentIndex]] = currentValue.trim().replace(/^"|"$/g, '');
        }

        data.push(obj);
    }

    return data;
}

// Format market cap
function formatMarketCap(value) {
    if (!value || value === '') return 'N/A';
    const num = parseFloat(value);
    if (isNaN(num)) return 'N/A';

    if (num >= 1e12) return (num / 1e12).toFixed(2) + 'T';
    if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
    if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
    return num.toFixed(2);
}

// Color scale for sectors
const sectorColors = {
    'Information Technology': '#1f77b4',
    'Financials': '#ff7f0e',
    'Healthcare': '#2ca02c',
    'Consumer Discretionary': '#d62728',
    'Industrials': '#9467bd',
    'Materials': '#8c564b',
    'Energy': '#e377c2',
    'Real Estate': '#bcbd22',
    'Utilities': '#17becf',
    'Consumer Staples': '#aec7e8',
    'Communication Services': '#ffbb78',
    'Sector': '#c5b0d5'
};

// Global state
let allStocks = [];
let selectedTicker = null;

// Load and initialize visualization
async function initVisualization() {
    try {
        // Load CSV data
        const response = await fetch('data/stock-descriptions.csv');
        const csvText = await response.text();
        allStocks = parseCSV(csvText);

        // Filter out stocks with missing ticker or sector
        allStocks = allStocks.filter(stock => stock.ticker && stock.sector);

        // Prepare data for visualization
        const stocks = allStocks.map((stock, index) => ({
            id: stock.ticker,
            ticker: stock.ticker,
            name: stock['full name'],
            sector: stock.sector,
            marketCap: stock.marketCap ? parseFloat(stock.marketCap) : null,
            rowIndex: index
        }));

        // Create bubble chart
        createBubbleChart(stocks);

        // Create table
        createTable(stocks);

    } catch (error) {
        console.error('Error loading data:', error);
    }
}

function createBubbleChart(stocks) {
    const margin = { top: 10, right: 10, bottom: 10, left: 10 };
    const container = document.getElementById('bubble-chart-container');
    const width = container.offsetWidth - margin.left - margin.right;
    const height = container.offsetHeight - margin.top - margin.bottom;

    const svg = d3.select('#bubble-chart')
        .attr('width', width + margin.left + margin.right)
        .attr('height', height + margin.top + margin.bottom)
        .append('g')
        .attr('transform', `translate(${margin.left},${margin.top})`);

    // Size scale - normalize market cap
    const maxMarketCap = d3.max(stocks.filter(s => s.marketCap), s => s.marketCap);
    const sizeScale = d3.scaleSqrt()
        .domain([0, maxMarketCap])
        .range([20, 80]);

    // Get unique sectors
    const sectors = [...new Set(stocks.map(s => s.sector))].sort();

    // Create force simulation
    const simulation = d3.forceSimulation(stocks)
        .force('x', d3.forceX()
            .x((d, i) => {
                // Position by sector - divide space into columns
                const sectorIndex = sectors.indexOf(d.sector);
                return (sectorIndex + 0.5) * (width / sectors.length);
            })
            .strength(0.1)
        )
        .force('y', d3.forceY(height / 2).strength(0.05))
        .force('collide', d3.forceCollide()
            .radius(d => {
                // Size based on market cap, or uniform size for ETFs
                if (d.marketCap) {
                    return sizeScale(d.marketCap) + 2;
                }
                return 35 + 2; // Uniform size for ETFs
            })
            .strength(0.9)
        )
        .force('charge', d3.forceManyBody().strength(-20))
        .on('tick', ticked);

    // Create circles
    const nodes = svg.selectAll('.node')
        .data(stocks, d => d.id)
        .enter()
        .append('g')
        .attr('class', 'node')
        .attr('data-ticker', d => d.ticker);

    nodes.append('circle')
        .attr('r', d => {
            if (d.marketCap) {
                return sizeScale(d.marketCap);
            }
            return 35; // Uniform size for ETFs
        })
        .attr('fill', d => sectorColors[d.sector] || '#cccccc')
        .attr('stroke', '#333')
        .attr('stroke-width', 1)
        .on('mouseenter', function(event, d) {
            // Show tooltip only if stock has market cap data (not ETF)
            if (d.marketCap) {
                showTooltip(event, d);
            }
        })
        .on('mouseleave', hideTooltip)
        .on('click', function(event, d) {
            event.stopPropagation();
            selectStock(d.ticker);
        });

    // Add labels
    nodes.append('text')
        .attr('text-anchor', 'middle')
        .attr('dy', '0.3em')
        .attr('font-size', '11px')
        .attr('font-weight', 'bold')
        .attr('fill', 'white')
        .attr('pointer-events', 'none')
        .text(d => d.ticker);

    function ticked() {
        nodes.attr('transform', d => `translate(${d.x},${d.y})`);
    }

    // Create legend
    createLegend(sectors);
}

function createLegend(sectors) {
    const legend = d3.select('#legend');

    const legendItems = legend.selectAll('.legend-item')
        .data(sectors)
        .enter()
        .append('div')
        .attr('class', 'legend-item');

    legendItems.append('div')
        .attr('class', 'legend-color')
        .style('background-color', d => sectorColors[d] || '#cccccc');

    legendItems.append('span')
        .text(d => d);
}

function createTable(stocks) {
    const tbody = d3.select('#table-body');

    const rows = tbody.selectAll('tr')
        .data(stocks, d => d.id)
        .enter()
        .append('tr')
        .attr('data-ticker', d => d.ticker)
        .on('click', function(event, d) {
            event.stopPropagation();
            selectStock(d.ticker);
        });

    rows.append('td').text(d => d.ticker);
    rows.append('td').text(d => d.name);
    rows.append('td').text(d => d.sector);
    rows.append('td').text(d => formatMarketCap(d.marketCap));
}

function showTooltip(event, d) {
    const tooltip = document.getElementById('tooltip');
    tooltip.innerHTML = `
        <strong>${d.ticker}</strong><br/>
        ${d.name}<br/>
        ${d.sector}
    `;
    tooltip.style.display = 'block';
    tooltip.style.left = (event.pageX + 10) + 'px';
    tooltip.style.top = (event.pageY + 10) + 'px';
}

function hideTooltip() {
    document.getElementById('tooltip').style.display = 'none';
}

function selectStock(ticker) {
    selectedTicker = ticker;

    // Update bubble chart highlighting
    d3.selectAll('.node')
        .classed('selected', d => d.ticker === ticker)
        .style('opacity', d => d.ticker === ticker ? 1 : 1);

    // Highlight bubble border
    d3.selectAll('.node circle')
        .style('stroke-width', d => d.ticker === ticker ? 3 : 1)
        .style('filter', d => d.ticker === ticker ? 'brightness(1.1)' : 'brightness(1)');

    // Update table highlighting
    d3.selectAll('#stock-table tbody tr')
        .classed('selected', d => d.ticker === ticker);
}

// Initialize on page load
document.addEventListener('DOMContentLoaded', initVisualization);

// Handle window resize
window.addEventListener('resize', () => {
    // Could add responsive resizing here if needed
});

